  "content": "{\n  \"protagonists\": [\n    {\n      \"name\": \"谢云敛\",\n      \"role\": \"主角\",\n      \"archetype\": \"清冷正道魁首\",\n      \"traits\": {\n        \"surface\": [\"清冷自持\", \"循规蹈矩\", \"完美师兄\"],\n        \"deep\": [\"离经叛道\", \"极度护短\", \"内心孤独\"],\n        \"core_conflict\": \"外在的完美正道楷模 vs 内心对正邪之分的质疑与对殷无咎的执念\"\n      },\n      \"motivation\": {\n        \"overt\": \"斩妖除魔，维护天衍宗声誉，追查当年救命恩人的下落\",\n        \"covert\": \"保护殷无咎不受伤害，哪怕与世界为敌\"\n      },\n      \"secret_fear\": \"害怕自己成为师尊那样'为了大义牺牲一切（包括爱人）'的人；害怕殷无咎因为自己而死\",\n      \"backstory\": \"天衍宗掌门玄机子亲传弟子，年轻一代天花板，修为元婴初期。自幼被灌输正邪不两立的思想。十年前在凡间历练时曾被一少年救过，那少年留下的玉佩是魔教之物，从此成为心结。\"\n    },\n    {\n      \"name\": \"殷无咎\",\n      \"role\": \"主角\",\n      \"archetype\": \"隐忍魔域少主\",\n      \"traits\": {\n        \"surface\": [\"邪魅狂狷\", \"玩世不恭\", \"心狠手辣\"],\n        \"deep\": [\"自卑\", \"温柔隐忍\", \"深情\"],\n        \"core_conflict\": \"外在的魔头形象 vs 内心渴望光明的温暖（谢云敛）\"\n      },\n      \"motivation\": {\n        \"overt\": \"一统魔域，向正道复仇，夺回属于古族的荣耀\",\n        \"covert\": \"活下去，并在暗处看着谢云敛成神，不让他沾染自己的污名\"\n      },\n      \"secret_fear\": \"害怕谢云敛看到自己满身血腥的样子；害怕自己体内的魔神之血失控伤害谢云敛\",\n      \"backstory\": \"上古魔神血脉觉醒者，修为元婴中期/后期（爆发力强但有反噬）。被正道追杀，被魔域收留。在魔域厮杀长大，唯一的温暖是十年前救过的小道士（谢云敛）。\"\n    }\n  ],\n  \"supporting_characters\": [\n    {\n      \"name\": \"玄机子\",\n      \"role\": \"反派/阻碍\",\n      \"function\": \"阻碍\",\n      \"archetype\": \"伪君子师尊\",\n      \"traits\": [\"道貌岸然\", \"极度固执\", \"冷血功利\"],\n      \"motivation\": {\n        \"overt\": \"维护正道苍生，铲除魔教\",\n        \"covert\": \"利用殷无咎的魔神之血开启飞升通道，为此不惜牺牲徒弟\"\n      },\n      \"secret_fear\": \"飞升失败，寿元耗尽老死凡间\",\n      \"relationship_to_protagonist\": \"谢云敛的师尊（利用对象），殷无咎的死敌。修为渡劫期（半步飞升），给主角造成绝望的压迫感。\"\n    },\n    {\n      \"name\": \"红药\",\n      \"role\": \"配角/助力\",\n      \"function\": \"助力\",\n      \"archetype\": \"魔域医仙\",\n      \"traits\": [\"毒舌\", \"护短\", \"医术高超\"],\n      \"motivation\": {\n        \"overt\": \"研制出解开魔血诅咒的药\",\n        \"covert\": \"报答殷无咎当年的救命之恩\"\n      },\n      \"secret_fear\": \"无法治好殷无咎，看着他魔血爆发而亡\",\n      \"relationship_to_protagonist\": \"殷无咎的下属兼好友，谢云敛的情敌（假象）。结局存活，是两人归隐后的见证者。\"\n    },\n    {\n      \"name\": \"萧长风\",\n      \"role\": \"配角/反转点\",\n      \"function\": \"反转点\",\n      \"archetype\": \"嫉妒师弟\",\n      \"traits\": [\"嫉妒\", \"阴险\", \"见风使舵\"],\n      \"motivation\": {\n        \"overt\": \"成为正道年轻一代第一人\",\n        \"covert\": \"毁掉谢云敛，取而代之\"\n      },\n      \"secret_fear\": \"永远活在谢云敛的阴影下\",\n      \"relationship_to_protagonist\": \"谢云敛的同门师弟，修为金丹大圆满/半步元婴。嫉妒谢云敛的天赋与地位，暗中勾结魔教反叛势力。\"\n    }\n  ],\n  \"relationship_dynamics\": [\n    {\n      \"characters\": [\"谢云敛\", \"殷无咎\"],\n      \"dynamic\": \"初期敌对（正魔殊途，互相试探） -> 中期共患难（秘境绑定，认出彼此，隐忍克制） -> 后期决裂（为保护对方而互相推开，虐点爆发） -> 结局和解（联手弑神，生死相依）\",\n      \"tension_source\": \"正邪身份对立、师门压力、魔血诅咒\"\n    },\n    {\n      \"characters\": [\"谢云敛\", \"玄机子\"],\n      \"dynamic\": \"初期敬重（师徒情深） -> 中期怀疑（发现师尊利用自己） -> 后期决裂（得知真相，拔剑相向）\",\n      \"tension_source\": \"价值观冲突、利用与被利用\"\n    },\n    {\n      \"characters\": [\"殷无咎\", \"红药\"],\n      \"dynamic\": \"初期上下级（信任） -> 中期战友（共同对抗正道） -> 后期助攻（红药点醒谢云敛）\",\n      \"tension_source\": \"无（纯粹的友谊/恩情）\"\n    }\n  ]\n}",
